function frame(now){requestAnimationFrame(frame);let dt=Math.min(.04,(now-last)/1000);last=now;if(document.hidden)return;tick+=dt;let playing=s.started&&!s.sleeping&&!modal(),dx=0,dy=0;if(playing){dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0);dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)}let moving=!!(dx||dy);if(moving){let len=Math.hypot(dx,dy);dx/=len;dy/=len;s.p.dir=dx<-.4?'left':dx>.4?'right':dy<0?'back':'front';if(s.room){let p=s.rp,v=dt*17;if(!indoorBlocked(p.x+dx*v,p.y))p.x+=dx*v;if(!indoorBlocked(p.x,p.y+dy*v))p.y+=dy*v}else{let p=s.p,v=dt*24;if(!blocked(p.x+dx*v,p.y))p.x+=dx*v;if(!blocked(p.x,p.y+dy*v))p.y+=dy*v}if(now-stepTime>380){tone(100+Math.random()*30,.06,.045);stepTime=now}}
 if(lastLight!==s.phase)syncWorldLight();
 if(s.cam.follow){let a=1-Math.exp(-dt*9);s.cam.x+=(s.p.x-s.cam.x)*a;s.cam.y+=(s.p.y-s.cam.y)*a}
 if(!s.room){let z=8*s.zoom;$('camera').style.transform=`translate(${vw/2-s.cam.x*z}px,${vh/2-s.cam.y*z}px) scale(${z})`;$('player').style.left=s.p.x+'px';$('player').style.top=s.p.y+'px';actor($('player'),s.p.dir,moving)}else{$('roomPlayer').style.left=s.rp.x+'%';$('roomPlayer').style.top=s.rp.y+'%';actor($('roomPlayer'),s.p.dir,moving)}
 $('cameraHint').hidden=s.cam.follow||!!s.room||!s.started;
 for(const n of npcs){
  if(s.room)break;
  const previous={index:n.index,t:n.t,forward:n.forward};
  let a=n.route[n.index-1],b=n.route[n.index],len=Math.hypot(a[0]-b[0],a[1]-b[1]);
  n.t+=dt*n.speed/len*(n.forward?1:-1);
  if(n.t>1){if(n.index<n.route.length-1){n.index++;n.t=0}else{n.forward=false;n.t=1}}
  if(n.t<0){if(n.index>1){n.index--;n.t=1}else{n.forward=true;n.t=0}}
  a=n.route[n.index-1];b=n.route[n.index];let x=a[0]+(b[0]-a[0])*n.t,y=a[1]+(b[1]-a[1])*n.t;
  if(blocked(x,y)){
   if(n.x){n.index=previous.index;n.t=previous.t;n.forward=!previous.forward;continue}
   // Initial placements that intersect a footprint are moved to a valid route sample before appearing.
   let found=false;for(let j=1;j<n.route.length&&!found;j++){let u=n.route[j-1],v=n.route[j];for(let t=.05;t<1;t+=.1){let xx=u[0]+(v[0]-u[0])*t,yy=u[1]+(v[1]-u[1])*t;if(!blocked(xx,yy)){n.index=j;n.t=t;x=xx;y=yy;found=true;break}}}
   if(!found){n.e.hidden=true;continue}
  }
  n.e.hidden=false;n.e.style.left=x+'px';n.e.style.top=y+'px';actor(n.e,Math.abs(x-n.x)>Math.abs(y-n.y)?x<n.x?'left':'right':y<n.y?'back':'front',true);n.x=x;n.y=y;
 }
 near=null;if(playing){if(s.room){let p=s.rp,v=roomSpots.map(v=>({...v,d:Math.hypot(p.x-v.x,p.y-v.y)})).sort((a,b)=>a.d-b.d)[0];if(v&&v.d<19)near=v}else{let p=s.p,v=buildings.filter(kindFor).map(b=>({b,d:Math.hypot(p.x-b[2]-b[4]/2,p.y-b[3]-b[5]-4)})).sort((a,b)=>a.d-b.d)[0];if(v&&v.d<13)near={label:'进入'+v.b[1],fn:()=>enter(v.b)};else{let v=placeSpots.find(v=>Math.hypot(p.x-v[2],p.y-v[3])<9);if(v)near={label:v[1],fn:()=>spot(v)}}let n=buildings.map(b=>({b,d:Math.hypot(p.x-b[2]-b[4]/2,p.y-b[3]-b[5]/2)})).sort((a,b)=>a.d-b.d)[0];$('location').textContent=n?.d<80?n.b[1]+'附近':'校园里'}}
 $('action').hidden=!near;if(near)$('action').querySelector('span').textContent=near.label;
 if(s.started)for(const id of ['minimap','bigMap'])$(id).querySelector('.map-player')?.setAttribute('transform',`translate(${s.p.x} ${s.p.y})`);
 ctx.clearRect(0,0,vw,vh);if(s.started&&!s.room&&!s.sleeping){for(let i=0;i<24;i++){let x=((i*.317%1)*vw+tick*(4+Math.sin(i)*2))%vw,y=((i*.173%1)*vh+Math.sin(tick*.2+i)*23+tick*2)%vh;ctx.fillStyle=s.phase>=4?'#efd5a877':'#e0e6c755';ctx.fillRect(x,y,2,1)}if(Math.floor(tick)%24===0&&now-stepTime>1200&&!s.muted){tone(s.phase===5?1500:1900,.12,.02);stepTime=now}}
}
requestAnimationFrame(frame);
$('startButton').disabled=true;
const worldReady=fetch('assets/world.svg').then(r=>{if(!r.ok)throw new Error('校园地图');return r.text()}).then(svg=>{$('worldArt').innerHTML=svg;syncWorldLight()});
Promise.all([...['front','back','side','dorm','canteen','class','morning'].map(n=>new Promise((resolve,reject)=>{let i=new Image();i.onload=resolve;i.onerror=()=>reject(n);i.src=`assets/${n}.svg`})),worldReady]).then(()=>{$('startButton').disabled=false;$('loadingText').textContent='建议戴上耳机 · 键盘与鼠标 · 自由漫游'}).catch(n=>{$('loadingText').textContent=`场景载入失败（${n.message||n}），请刷新重试。`});
